"use client"

import { useEffect, useRef, useState } from "react"

interface SmokeParticle {
  x: number
  y: number
  vx: number
  vy: number
  life: number
  size: number
  hue: number
  angle: number
}

export function RainbowCursor() {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const particlesRef = useRef<SmokeParticle[]>([])
  const mouseRef = useRef({ x: 0, y: 0, prevX: 0, prevY: 0 })
  const animationFrameRef = useRef<number>()
  const hueRef = useRef(0)
  const cursorDecorationRef = useRef<HTMLDivElement>(null)
  const [mousePosition, setMousePosition] = useState({ x: -100, y: -100 })
  const [cursorTrail, setCursorTrail] = useState<Array<{ x: number; y: number; hue: number }>>([])

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return

    const ctx = canvas.getContext("2d")
    if (!ctx) return

    const setCanvasSize = () => {
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
    }

    setCanvasSize()
    window.addEventListener("resize", setCanvasSize)

    const handleMouseMove = (e: MouseEvent) => {
      const dx = e.clientX - mouseRef.current.x
      const dy = e.clientY - mouseRef.current.y
      const distance = Math.sqrt(dx * dx + dy * dy)

      mouseRef.current.prevX = mouseRef.current.x
      mouseRef.current.prevY = mouseRef.current.y
      mouseRef.current.x = e.clientX
      mouseRef.current.y = e.clientY

      // Update cursor decoration position with smooth interpolation
      requestAnimationFrame(() => {
        setMousePosition({ x: e.clientX, y: e.clientY })
        
        // Update trail
        setCursorTrail((prev) => {
          const newTrail = [...prev, { x: e.clientX, y: e.clientY, hue: hueRef.current }]
          // Keep trail limited to 6 points
          return newTrail.slice(-6)
        })
      })

      // Create flexible rainbow smoke particles
      if (distance > 0.5) {
        const particleCount = Math.min(Math.floor(distance / 5) + 2, 8)
        
        for (let i = 0; i < particleCount; i++) {
          const angle = (Math.atan2(dy, dx) + (Math.random() - 0.5) * 1.5) % (Math.PI * 2)
          const speed = Math.random() * 0.5 + 0.3
          const spread = (Math.random() - 0.5) * 40
          
          particlesRef.current.push({
            x: e.clientX + (Math.random() - 0.5) * 20,
            y: e.clientY + (Math.random() - 0.5) * 20,
            vx: Math.cos(angle) * speed + (Math.random() - 0.5) * 0.3,
            vy: Math.sin(angle) * speed + (Math.random() - 0.5) * 0.3 - 0.2,
            life: 1,
            size: Math.random() * 25 + 15,
            hue: (hueRef.current + i * 15 + Math.random() * 30) % 360,
            angle: angle + (Math.random() - 0.5) * 0.5,
          })
        }
        hueRef.current = (hueRef.current + 3) % 360
      }
    }

    const animate = () => {
      // Clear with fade effect for trailing smoke
      ctx.fillStyle = "rgba(0, 0, 0, 0.03)"
      ctx.fillRect(0, 0, canvas.width, canvas.height)

      particlesRef.current = particlesRef.current.filter((particle) => {
        // More flexible movement with turbulence
        particle.vx += (Math.random() - 0.5) * 0.15
        particle.vy += (Math.random() - 0.5) * 0.15 - 0.015
        particle.x += particle.vx
        particle.y += particle.vy
        particle.life -= 0.0025
        particle.size += 0.5
        particle.angle += (Math.random() - 0.5) * 0.1

        if (particle.life <= 0) return false

        ctx.save()
        ctx.globalAlpha = particle.life * 0.7
        
        // Enhanced blur for smoother smoke effect
        ctx.filter = `blur(${particle.size / 3}px)`

        // Create flexible rainbow gradient
        const gradient = ctx.createRadialGradient(
          particle.x, 
          particle.y, 
          0, 
          particle.x, 
          particle.y, 
          particle.size
        )
        
        const hue1 = particle.hue
        const hue2 = (particle.hue + 60) % 360
        const hue3 = (particle.hue + 120) % 360
        
        gradient.addColorStop(0, `hsla(${hue1}, 90%, 65%, ${particle.life * 0.9})`)
        gradient.addColorStop(0.5, `hsla(${hue2}, 85%, 60%, ${particle.life * 0.5})`)
        gradient.addColorStop(1, `hsla(${hue3}, 80%, 55%, 0)`)

        ctx.fillStyle = gradient
        ctx.beginPath()
        ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2)
        ctx.fill()
        ctx.restore()

        return true
      })

      animationFrameRef.current = requestAnimationFrame(animate)
    }

    window.addEventListener("mousemove", handleMouseMove, { passive: true })
    animate()

    return () => {
      window.removeEventListener("resize", setCanvasSize)
      window.removeEventListener("mousemove", handleMouseMove)
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current)
      }
    }
  }, [])

  return (
    <div>
      {/* Rainbow smoke canvas */}
      <canvas ref={canvasRef} className="fixed inset-0 pointer-events-none z-50" style={{ mixBlendMode: "screen" }} />
      
      {/* Mouse decoration with rainbow glow */}
      {mousePosition.x > 0 && mousePosition.y > 0 && (
        <>
          {/* Cursor trail */}
          {cursorTrail.map((point, index) => {
            const opacity = (index + 1) / Math.max(cursorTrail.length, 1) * 0.4
            const size = 2 + (index / Math.max(cursorTrail.length, 1)) * 3
            return (
              <div
                key={index}
                className="fixed pointer-events-none z-[9998] rounded-full"
                style={{
                  left: `${point.x}px`,
                  top: `${point.y}px`,
                  transform: 'translate(-50%, -50%)',
                  width: `${size}px`,
                  height: `${size}px`,
                  background: `hsl(${point.hue}, 80%, 60%)`,
                  boxShadow: `0 0 ${size * 2}px hsl(${point.hue}, 80%, 60%)`,
                  opacity: opacity,
                  transition: 'opacity 0.1s ease-out',
                }}
              />
            )
          })}
          
          {/* Main cursor decoration */}
          <div
            ref={cursorDecorationRef}
            className="fixed pointer-events-none z-[9999] rainbow-cursor-decoration"
            style={{
              left: `${mousePosition.x}px`,
              top: `${mousePosition.y}px`,
              transform: 'translate(-50%, -50%)',
            }}
          >
            <div className="w-4 h-4 rounded-full bg-gradient-to-br from-violet-400 via-purple-500 to-pink-500 shadow-lg shadow-violet-500/50 animate-pulse" />
            <div className="absolute inset-0 w-8 h-8 rounded-full bg-gradient-to-br from-violet-400/30 via-purple-500/30 to-pink-500/30 blur-md -translate-x-1/2 -translate-y-1/2 left-1/2 top-1/2" />
            <div className="absolute inset-0 w-12 h-12 rounded-full bg-gradient-to-br from-violet-400/10 via-purple-500/10 to-pink-500/10 blur-xl -translate-x-1/2 -translate-y-1/2 left-1/2 top-1/2" />
          </div>
        </>
      )}
    </div>
  )
}
